def canonical(value):
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), allow_nan=False
    )

def digest(value):
    return hashlib.sha256(canonical(value).encode("utf-8")).hexdigest()

def require_sha(value):
    if not isinstance(value, str) or re.fullmatch("[0-9a-f]{64}", value) is None:
        raise ValueError("Expected lowercase SHA-256 evidence digest")
    return value

def require_text(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("Expected nonempty text identifier")
    return value

def require_day(value):
    require_text(value)
    parsed = date.fromisoformat(value)
    if parsed.isoformat() != value:
        raise ValueError("Expected canonical ISO calendar date")
    return value

def apply_event(event_id, payload, operation):
    require_text(event_id)
    payload_sha = digest(payload)
    db.execute("BEGIN IMMEDIATE")
    try:
        prior = db.execute(
            "SELECT payload_sha, result_json FROM events WHERE event_id = ?",
            (event_id,),
        ).fetchone()
        if prior is not None:
            if prior[0] != payload_sha:
                raise ValueError("Event identifier reused with different payload")
            result = json.loads(prior[1])
        else:
            db.execute(
                "INSERT INTO events(event_id, payload_sha) VALUES (?, ?)",
                (event_id, payload_sha),
            )
            result = operation()
            db.execute(
                "UPDATE events SET result_json = ? WHERE event_id = ?",
                (canonical(result), event_id),
            )
        db.execute("COMMIT")
        return result
    except BaseException:
        if db.in_transaction:
            db.execute("ROLLBACK")
        raise

def intake(event_id, asset_id, play, evidence_sha,
           buyer_points, documentation_points, repeatability_points):
    require_text(asset_id)
    require_sha(evidence_sha)
    values = (
        (buyer_points, 50),
        (documentation_points, 30),
        (repeatability_points, 20),
    )
    for value, maximum in values:
        if type(value) is not int or not 0 <= value <= maximum:
            raise ValueError("Readiness component outside assigned range")
    score = sum(value for value, maximum in values)
    payload = {
        "kind": "intake", "asset_id": asset_id, "play": play,
        "evidence_sha": evidence_sha,
        "buyer_points": buyer_points,
        "documentation_points": documentation_points,
        "repeatability_points": repeatability_points,
    }
    def operation():
        db.execute(
            "INSERT INTO assets(asset_id, play, evidence_sha, readiness) "
            "VALUES (?, ?, ?, ?)",
            (asset_id, play, evidence_sha, score),
        )
        return {"asset_id": asset_id, "readiness": score, "revision": 0}
    return apply_event(event_id, payload, operation)

def transition(event_id, asset_id, expected_revision, action, evidence):
    require_text(asset_id)
    if type(expected_revision) is not int or expected_revision < 0:
        raise ValueError("Expected nonnegative integer revision")
    evidence = json.loads(canonical(evidence))
    require_text(evidence["reviewer"])
    require_sha(evidence["review_sha"])
    payload = {
        "kind": "transition", "asset_id": asset_id,
        "expected_revision": expected_revision,
        "action": action, "evidence": evidence,
    }
    def operation():
        row = db.execute(
            "SELECT state, revision, evidence_sha, readiness "
            "FROM assets WHERE asset_id = ?", (asset_id,)
        ).fetchone()
        if row is None or row[1] != expected_revision:
            raise ValueError("Asset missing or revision already consumed")
        state, revision, source_sha, readiness = row
        if action == "verify" and state == "intake":
            if evidence.get("rights_sha") != source_sha or readiness < 70:
                raise ValueError("Rights packet or readiness requirement failed")
            target = "verified"
        elif action == "reserve" and state == "verified":
            require_sha(evidence["escrow_terms_sha"])
            target = "escrow_pending"
        elif action == "activate" and state in ("verified", "escrow_pending"):
            if state == "escrow_pending":
                require_sha(evidence["escrow_receipt_sha"])
            elif evidence.get("escrow_required") is not False:
                raise ValueError("Required escrow must enter pending state first")
            starts_on = require_day(evidence["starts_on"])
            ends_on = require_day(evidence["ends_on"])
            if starts_on > ends_on:
                raise ValueError("Contract date interval is reversed")
            contract_id = require_text(evidence["contract_id"])
            licensee = require_text(evidence["licensee"])
            scope_sha = require_sha(evidence["scope_sha"])
            signed_sha = require_sha(evidence["signed_sha"])
            db.execute(
                "INSERT INTO contracts "
                "(contract_id, asset_id, licensee, scope_sha, signed_sha, "
                "starts_on, ends_on, currency) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                (contract_id, asset_id, licensee, scope_sha, signed_sha,
                 starts_on, ends_on, "USD"),
            )
            target = "active"
        elif action == "block":
            require_text(evidence["reason"])
            target = "blocked"
        else:
            raise ValueError("Transition is not permitted from current state")
        changed = db.execute(
            "UPDATE assets SET state = ?, revision = revision + 1 "
            "WHERE asset_id = ? AND revision = ?",
            (target, asset_id, expected_revision),
        ).rowcount
        if changed != 1:
            raise RuntimeError("Revision update did not affect exactly one asset")
        return {"asset_id": asset_id, "state": target, "revision": revision + 1}
    return apply_event(event_id, payload, operation)

def require_cents(value):
    if type(value) is not int or not 0 < value <= 1000000000000:
        raise ValueError("Expected positive bounded integer cents")
    return value

def balance(contract_id, account):
    return db.execute(
        "SELECT COALESCE(SUM(e.amount_cents), 0) "
        "FROM entries e JOIN journals j ON j.journal_id = e.journal_id "
        "WHERE j.status = 'posted' AND j.contract_id = ? AND e.account = ?",
        (contract_id, account),
    ).fetchone()[0]

def post(event_id, economic_key, contract_id, lines):
    if not db.in_transaction:
        raise RuntimeError("Posting requires the enclosing event transaction")
    lines = [(account, amount) for account, amount in lines if amount != 0]
    if len(lines) < 2 or any(type(amount) is not int for account, amount in lines):
        raise ValueError("Journal requires at least two integer-cent lines")
    if sum(amount for account, amount in lines) != 0:
        raise ValueError("Journal debits and credits must balance")
    db.execute(
        "INSERT INTO journals(journal_id, event_id, economic_key, contract_id) "
        "VALUES (?, ?, ?, ?)",
        (event_id, event_id, economic_key, contract_id),
    )
    db.executemany(
        "INSERT INTO entries(journal_id, line_number, account, amount_cents) "
        "VALUES (?, ?, ?, ?)",
        [(event_id, number, account, amount)
         for number, (account, amount) in enumerate(lines, 1)],
    )
    db.execute(
        "UPDATE journals SET status = 'posted' WHERE journal_id = ?",
        (event_id,),
    )
    return {"journal_id": event_id, "status": "posted"}

def earn(event_id, contract_id, invoice_ref, earned_on, amount_cents, memo_sha):
    require_text(contract_id)
    require_text(invoice_ref)
    require_day(earned_on)
    require_cents(amount_cents)
    require_sha(memo_sha)
    payload = {
        "kind": "earn", "contract_id": contract_id,
        "invoice_ref": invoice_ref, "earned_on": earned_on,
        "amount_cents": amount_cents, "memo_sha": memo_sha,
    }
    def operation():
        row = db.execute(
            "SELECT a.state, c.starts_on, c.ends_on FROM contracts c "
            "JOIN assets a ON a.asset_id = c.asset_id WHERE c.contract_id = ?",
            (contract_id,),
        ).fetchone()
        if row is None or row[0] != "active" or not row[1] <= earned_on <= row[2]:
            raise ValueError("Contract is inactive or earned date is outside term")
        available = max(0, -balance(contract_id, "customer_credit"))
        applied = min(amount_cents, available)
        key = "earn:" + canonical([contract_id, invoice_ref])
        return post(event_id, key, contract_id, [
            ("customer_credit", applied),
            ("receivable", amount_cents - applied),
            ("license_revenue", -amount_cents),
        ])
    return apply_event(event_id, payload, operation)

def receive(event_id, contract_id, bank_ref, value_date, amount_cents, source_sha):
    require_text(contract_id)
    require_text(bank_ref)
    require_day(value_date)
    require_cents(amount_cents)
    require_sha(source_sha)
    payload = {
        "kind": "receive", "contract_id": contract_id,
        "bank_ref": bank_ref, "value_date": value_date,
        "amount_cents": amount_cents, "source_sha": source_sha,
    }
    def operation():
        exists = db.execute(
            "SELECT 1 FROM contracts WHERE contract_id = ?", (contract_id,)
        ).fetchone()
        if exists is None:
            raise ValueError("Receipt requires an identified contract")
        outstanding = max(0, balance(contract_id, "receivable"))
        applied = min(amount_cents, outstanding)
        key = "cash:" + canonical([bank_ref])
        return post(event_id, key, contract_id, [
            ("cash", amount_cents),
            ("receivable", -applied),
            ("customer_credit", -(amount_cents - applied)),
        ])
    return apply_event(event_id, payload, operation)

def qa():
    db.execute("BEGIN")
    try:
        integrity = db.execute("PRAGMA integrity_check").fetchall()
        if integrity != [("ok",)]:
            raise RuntimeError("Database integrity check failed")
        if db.execute("PRAGMA foreign_key_check").fetchall():
            raise RuntimeError("Foreign-key check failed")
        if db.execute(
            "SELECT COUNT(*) FROM journals WHERE status <> 'posted'"
        ).fetchone()[0]:
            raise RuntimeError("Committed draft journal requires investigation")
        bad_journals = db.execute(
            "SELECT j.journal_id FROM journals j "
            "LEFT JOIN entries e ON e.journal_id = j.journal_id "
            "GROUP BY j.journal_id "
            "HAVING COUNT(e.line_number) < 2 "
            "OR COALESCE(SUM(e.amount_cents), 0) <> 0"
        ).fetchall()
        if bad_journals:
            raise RuntimeError("Journal balance check failed")
        rows = reconciliation_rows()
        for row in rows:
            if row["difference_cents"] != 0:
                raise RuntimeError("Contract reconciliation difference detected")
            if row["receivable_cents"] < 0 or row["credit_cents"] < 0:
                raise RuntimeError("Contract allocation balance requires review")
        result = {
            "contracts_checked": len(rows),
            "earned_cents": sum(row["earned_cents"] for row in rows),
            "collected_cents": sum(row["collected_cents"] for row in rows),
            "receivable_cents": sum(row["receivable_cents"] for row in rows),
            "credit_cents": sum(row["credit_cents"] for row in rows),
        }
        db.execute("COMMIT")
        return result
    except BaseException:
        if db.in_transaction:
            db.execute("ROLLBACK")
        raise

